def clamp(value):
    return max(0, min(100, int(value)))


print(clamp("85"), clamp(140), clamp(-3.7))

import json


def parse(text):
    try:
        out = json.loads(text)
    except json.JSONDecodeError:
        return {"error": "unparseable response: " + text[:10]}
    return out


print(parse('{"answer": "B"}')["answer"], parse("Sure! Here is")["error"])

class APIStatusError(Exception):
    pass


class RateLimitError(APIStatusError):
    pass


def handle(exc):
    try:
        raise exc
    except APIStatusError:
        return "status"
    except RateLimitError:
        return "rate limit"


print(handle(RateLimitError()), handle(APIStatusError()))
